/** upright human figure ~1.75 m, hi-vis torso */
function figure(vestCol) {
  return [
    { box: [0, 0, 0.11, 0.26, 0.85, 0.17], col: C.navy }, // leg
    { box: [0, 0, -0.11, 0.26, 0.85, 0.17], col: C.navy },
    { box: [0, 0.85, 0, 0.42, 0.62, 0.27], col: vestCol }, // torso
    { box: [0, 0.9, 0.29, 0.16, 0.55, 0.14], col: vestCol }, // arm
    { box: [0, 0.9, -0.29, 0.16, 0.55, 0.14], col: vestCol },
    { box: [0, 1.5, 0, 0.21, 0.24, 0.21], col: C.skin }, // head
  ];
}

// ---- write package ----------------------------------------------------
mkdirSync(ROOT, { recursive: true });

writeFileSync(
  path.join(ROOT, 'manifest.json'),
  JSON.stringify(
    {
      dependencies: [],
      content_type: 'MISC',
      title: 'Aus Emergency Dispatcher — Scene Objects',
      manufacturer: 'Aus Emergency Dispatcher',
      creator: 'Aus Emergency Dispatcher',
      package_version: '1.3.0',
      minimum_game_version: '1.0.0',
      release_notes: { neutral: { LastUpdate: '', OlderHistory: '' } },
    },
    null,
    2,
  ),
);

const layout = { content: [] };
// MSFS layout.json `date` is a Windows FILETIME (100 ns ticks since 1601-01-01).
// A real value (not 0) keeps the sim from treating the package as stale/invalid.
const FILETIME = BigInt(Date.now()) * 10000n + 116444736000000000n;
function addFile(rel, buf) {
  const abs = path.join(ROOT, rel);
  mkdirSync(path.dirname(abs), { recursive: true });
  writeFileSync(abs, buf);
  layout.content.push({ path: rel.replace(/\\/g, '/'), size: buf.length, date: Number(FILETIME) });
}

// NOTE: MSFS rejects a Community package that has ANY unexpected file at its
// root, so this package contains ONLY manifest.json + layout.json + SimObjects/.
// (Credits live in the repo and in Documents\Aus Emergency Dispatcher\CREDITS.md.)

// Minimal, spec-correct sim.cfg for a scenery prop that SimConnect
// `AICreateSimulatedObject` will spawn: [Version] + [General] category=SimpleObject
// (a "Dynamic" SimObject) + [fltsim.0] with just a title and a model folder.
// NO base_container (the old relative path was invalid and broke the object) and
// no aircraft-only keys.
function simCfg(m) {
  return (
    `[Version]\nmajor = 1\nminor = 0\n\n` +
    `[General]\ncategory = SimpleObject\n\n` +
    `[fltsim.0]\ntitle = ${m.title}\nmodel = \ntexture = \n` +
    `description = ${m.desc} (Aus Emergency Dispatcher)\n`
  );
}

for (const m of MODELS) {
  const { gltf, bin } = modelGltf(m.title, m.parts);
  const base = `SimObjects/${m.title}`;
  addFile(`${base}/model/${m.title}.gltf`, Buffer.from(gltf));
  addFile(`${base}/model/${m.title}.bin`, bin);
  addFile(`${base}/model/model.cfg`, Buffer.from(`[MODELS]\nnormal = ${m.title}.gltf\n`));
  addFile(`${base}/sim.cfg`, Buffer.from(simCfg(m)));
}

writeFileSync(path.join(ROOT, 'layout.json'), JSON.stringify(layout, null, 2));

console.log(`Built ${MODELS.length} models -> ${ROOT}`);
console.log('Titles:', MODELS.map((m) => m.title).join(', '));
